var ok = rows.some(function (r) {
  var st = r.querySelector('.st');
  return r.innerText.indexOf('Ada') >= 0 && st && st.textContent.trim() === 'Aktif';
});
var m = document.getElementById('modal');
return String(ok && m && !m.classList.contains('open'));
